package com.codeinc.opencode.wire

import com.codeinc.opencode.gen.common.v1.Model
import com.codeinc.opencode.gen.currency.v1.OcpCurrencyService
import com.codeinc.opencode.gen.currency.v1.validate
import com.google.protobuf.ByteString
import dev.bmcreations.protovalidate.ValidationResult
import kotlin.test.Test
import kotlin.test.assertIs

// The protobuf-java artifact's validators were generated by protovalidate-kt in java mode and
// now run against the multiplatform 0.2.0 runtime. Android will resolve that runtime for both
// artifacts, so the old call path has to keep working against it.
class ProtobufJavaValidateTest {
    @Test
    fun javaValidatorsRunOnTheSharedRuntime() {
        fun request(mintLength: Int) = OcpCurrencyService.StreamLiveMintDataRequest.newBuilder()
            .setRequest(
                OcpCurrencyService.StreamLiveMintDataRequest.Request.newBuilder()
                    .addMints(Model.SolanaAccountId.newBuilder().setValue(ByteString.copyFrom(ByteArray(mintLength)))),
            )
            .build()

        assertIs<ValidationResult.Valid>(request(32).validate())
        assertIs<ValidationResult.Invalid>(request(31).validate())
    }
}
